// Cloudflare Pages Function — speed-test upload endpoint (28 Nov 2026, global batch item 2).
//
// POST /speedtest-upload — the Internet Speed & Ping Test tool posts
// generated bytes here so upload speed is measured against OUR OWN
// origin (eduvelto.com), not a third party. The body is read and
// discarded; nothing is stored, nothing is forwarded anywhere. The
// response only reports how many bytes arrived, so the tool can time
// the round trip honestly.
//
// Routing note: this static route (/speedtest-upload) takes precedence
// over the catch-all functions/[[path]].js SPA fallback.
export async function onRequestPost(context) {
  const buf = await context.request.arrayBuffer();
  return new Response(JSON.stringify({ received: buf.byteLength }), {
    status: 200,
    headers: {
      'content-type': 'application/json',
      'cache-control': 'no-store',
      'access-control-allow-origin': '*',
    },
  });
}

export async function onRequest(context) {
  if (context.request.method === 'POST') return onRequestPost(context);
  return new Response(JSON.stringify({ error: 'Use POST with a body to measure upload speed.' }), {
    status: 405,
    headers: { 'content-type': 'application/json' },
  });
}
